UPDATE knowledge_entries SET related_ids=(SELECT COALESCE(json_group_array(value),'[]') FROM json_each(knowledge_entries.related_ids) WHERE type='text') WHERE related_ids IS NOT NULL AND json_valid(related_ids) AND EXISTS (SELECT 1 FROM json_each(knowledge_entries.related_ids) WHERE type!='text');
UPDATE curation_actions SET id=substr(id,1,8)||'-'||substr(id,9,4)||'-'||substr(id,13,4)||'-'||substr(id,17,4)||'-'||substr(id,21,12) WHERE length(id)=32 AND id NOT GLOB '*[^0-9a-f]*' AND NOT EXISTS (SELECT 1 FROM curation_actions o WHERE o.id=substr(curation_actions.id,1,8)||'-'||substr(curation_actions.id,9,4)||'-'||substr(curation_actions.id,13,4)||'-'||substr(curation_actions.id,17,4)||'-'||substr(curation_actions.id,21,12));
